import { randomUUID } from "node:crypto";
import { lstat, readFile, rename, rm, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

// This bootstrap uses Node built-ins only, so it can run before installing devDependencies.
function object(value: unknown, label: string): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${label} 必须是 JSON 对象`);
  }
  return value as Record<string, unknown>;
}

const path = resolve("package.json");
const metadata = await lstat(path);
if (!metadata.isFile() || metadata.isSymbolicLink()) {
  throw new Error("package.json 必须是普通文件，不能是符号链接。未写入文件。");
}
const original = await readFile(path, "utf8");
const pkg = object(JSON.parse(original), "package.json");
const required = object(
  JSON.parse(
    await readFile(new URL("./project-config.json", import.meta.url), "utf8"),
  ),
  "project-config.json",
);
if (pkg.type !== "module") {
  throw new Error(
    "此预设用于 TypeScript ESM 项目，请先明确将 package.json 的 type 设为 module。未写入文件。",
  );
}
const conflicts: string[] = [];
for (const field of ["scripts", "devDependencies", "lint-staged"]) {
  const current = object(pkg[field] ?? {}, field);
  const additions = object(required[field], field);
  for (const [name, value] of Object.entries(additions)) {
    if (current[name] !== undefined && current[name] !== value) {
      conflicts.push(
        `${field}.${name}: 当前 ${JSON.stringify(current[name])}，预设 ${JSON.stringify(value)}`,
      );
    }
  }
  pkg[field] = { ...additions, ...current };
}
if (conflicts.length) {
  throw new Error(
    `检测到已有配置冲突，请审查并手动合并后重试。未写入文件。\n${conflicts.join("\n")}`,
  );
}
const next = `${JSON.stringify(pkg, null, 2)}\n`;
if (next !== original) {
  const temporary = `${path}.${randomUUID()}.tmp`;
  try {
    await writeFile(temporary, next, { flag: "wx", mode: metadata.mode });
    // Best-effort conflict detection; rename keeps a failed write from truncating the original.
    const current = await lstat(path);
    if (
      current.isSymbolicLink() ||
      (await readFile(path, "utf8")) !== original
    ) {
      throw new Error("package.json 已被其他进程修改，请重试。");
    }
    await rename(temporary, path);
  } finally {
    await rm(temporary, { force: true });
  }
}
console.log(
  "已补齐质量检查脚本和开发依赖。接下来运行 npm install；已有 Git 仓库会自动启用 Husky。",
);

import { useCallback, useState } from "react";
import { Button } from "../ui/Button";
import { TaskDialog } from "./taskDialog";
import { TaskTable } from "./taskTable";
import { Sidebar } from "./Sidebar";
import { TaskStatistics } from "./TaskStatistics";
import { decodeTasks, saveTasks, storageKey } from "../../lib/tasks";
import type { Task } from "../../lib/tasks";

function readTasks(): { tasks: Task[]; loadError: string } {
  try {
    return {
      tasks: decodeTasks(localStorage.getItem(storageKey)),
      loadError: "",
    };
  } catch (error) {
    return {
      tasks: [],
      loadError: error instanceof Error ? error.message : "读取任务失败",
    };
  }
}

export function App() {
  // localStorage 同步读取，初始化即可完成；失败状态保留给用户重试。
  const [{ tasks, loadError }, setTaskState] = useState(readTasks);
  const [notice, setNotice] = useState("");
  const [editor, setEditor] = useState<{ task: Task | null } | null>(null);

  function load() {
    setTaskState(readTasks());
  }

  // 列定义依赖编辑入口；稳定引用避免无关更新重建 TanStack 的列配置。
  const edit = useCallback((task?: Task) => {
    setEditor({ task: task ?? null });
  }, []);

  function save(task: Task) {
    const next = editor?.task
      ? tasks.map((item) => (item.id === task.id ? task : item))
      : [task, ...tasks];
    saveTasks(localStorage, next);
    setTaskState({ tasks: next, loadError: "" });
    setNotice(editor?.task ? "任务已更新" : "任务已创建");
  }

  return (
    <div className="min-h-screen md:grid md:grid-cols-[220px_1fr]">
      <Sidebar />
      <main className="mx-auto w-full max-w-6xl px-5 py-8 md:px-10 md:py-10">
        <div className="text-xs text-slate-500">工作空间 / 任务</div>
        <header className="mt-7 flex flex-wrap items-end justify-between gap-4">
          <div>
            <h1 className="text-3xl font-semibold tracking-tight">
              任务工作台
            </h1>
            <p className="mt-2 text-sm text-slate-500">
              把计划变成可追踪的进展。
            </p>
          </div>
          <Button disabled={Boolean(loadError)} onClick={() => edit()}>
            ＋ 新建任务
          </Button>
        </header>
        <TaskStatistics tasks={tasks} />
        {loadError ? (
          <section
            aria-label="任务列表"
            className="rounded-2xl border border-slate-200 bg-white p-5 md:p-6"
          >
            <div role="alert" className="rounded-xl bg-red-50 p-6 text-red-800">
              <p>{loadError}</p>
              <button type="button" className="mt-3 underline" onClick={load}>
                重新读取
              </button>
            </div>
          </section>
        ) : (
          <TaskTable tasks={tasks} notice={notice} onEdit={edit} />
        )}
        <footer className="mt-6 text-xs text-slate-400">
          本地工作台 · 不跨设备同步
        </footer>
      </main>
      {editor && (
        <TaskDialog
          task={editor.task}
          onSave={save}
          onClose={() => setEditor(null)}
        />
      )}
    </div>
  );
}

import { useState } from "react";
import { Dialog } from "@base-ui/react/dialog";
import { useForm } from "react-hook-form";
import { Button } from "../../ui/Button";
import { FormField } from "../../ui/FormField";
import { statuses } from "../../../lib/tasks";
import type { Task } from "../../../lib/tasks";

type Values = Pick<Task, "title" | "owner" | "status">;

interface TaskDialogProps {
  task: Task | null;
  onSave: (task: Task) => void;
  onClose: () => void;
}

const inputClass =
  "w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm";

export function TaskDialog({ task, onSave, onClose }: TaskDialogProps) {
  const [saveError, setSaveError] = useState("");
  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<Values>({
    defaultValues: task
      ? { title: task.title, owner: task.owner, status: task.status }
      : { title: "", owner: "", status: "待处理" },
  });

  function showSaveError(error: unknown) {
    setSaveError(error instanceof Error ? error.message : "保存失败，请重试");
  }

  const submit = handleSubmit((values) => {
    setSaveError("");
    try {
      onSave({
        ...values,
        title: values.title.trim(),
        owner: values.owner.trim(),
        id: task?.id ?? crypto.randomUUID(),
      });
      onClose();
    } catch (error) {
      showSaveError(error);
    }
  });

  return (
    <Dialog.Root
      open
      onOpenChange={(open) => {
        if (!open && !isSubmitting) onClose();
      }}
    >
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 bg-slate-950/30" />
        <Dialog.Popup className="fixed left-1/2 top-1/2 max-h-[90vh] w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 overflow-y-auto rounded-2xl bg-white p-7 shadow-xl">
          <Dialog.Title className="text-xl font-semibold">
            {task ? "编辑任务" : "新建任务"}
          </Dialog.Title>
          <Dialog.Description className="mt-2 text-sm text-slate-500">
            明确任务名称和负责人，方便后续跟踪。
          </Dialog.Description>
          <form
            className="mt-6 grid gap-5"
            onSubmit={(event) => {
              void submit(event).catch(showSaveError);
            }}
            noValidate
          >
            <FormField
              id="title"
              label="任务名称"
              error={errors.title?.message}
            >
              <input
                id="title"
                autoComplete="off"
                className={inputClass}
                aria-invalid={Boolean(errors.title)}
                aria-describedby={errors.title ? "title-error" : undefined}
                {...register("title", {
                  validate: (value) =>
                    value.trim().length > 0 || "请输入任务名称",
                  maxLength: {
                    value: 100,
                    message: "任务名称最多 100 个字符",
                  },
                })}
              />
            </FormField>
            <FormField id="owner" label="负责人" error={errors.owner?.message}>
              <input
                id="owner"
                className={inputClass}
                aria-invalid={Boolean(errors.owner)}
                aria-describedby={errors.owner ? "owner-error" : undefined}
                {...register("owner", {
                  maxLength: { value: 50, message: "负责人最多 50 个字符" },
                })}
              />
            </FormField>
            <FormField id="status" label="状态">
              <select
                id="status"
                className={inputClass}
                {...register("status")}
              >
                {statuses.map((status) => (
                  <option key={status}>{status}</option>
                ))}
              </select>
            </FormField>
            {saveError && (
              <p role="alert" className="text-sm text-red-700">
                保存失败：{saveError}。输入已保留，请重试。
              </p>
            )}
            <div className="mt-2 flex justify-end gap-3">
              <Dialog.Close
                className="rounded-lg px-4 py-2 text-sm text-slate-600"
                disabled={isSubmitting}
              >
                取消
              </Dialog.Close>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting ? "保存中…" : "保存任务"}
              </Button>
            </div>
          </form>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

import type { Task } from "../../lib/tasks";

export function TaskStatistics({ tasks }: { tasks: Task[] }) {
  return (
    <div className="my-8 grid grid-cols-3 gap-3 md:gap-5">
      {[
        { label: "全部任务", value: tasks.length },
        {
          label: "进行中",
          value: tasks.filter((task) => task.status === "进行中").length,
        },
        {
          label: "已完成",
          value: tasks.filter((task) => task.status === "已完成").length,
        },
      ].map((item) => (
        <div
          key={item.label}
          className="rounded-xl border border-slate-200 bg-white p-5"
        >
          <p className="text-xs text-slate-500">{item.label}</p>
          <p className="mt-3 text-3xl font-semibold tabular-nums">
            {item.value}
          </p>
        </div>
      ))}
    </div>
  );
}

